update country_flag_history set notes_fr = 'Les armoiries accordées en 1959, avec le lion britannique et le dragon chinois, figurent sur le Blue Ensign jusqu''à la rétrocession du 1er juillet 1997.', notes_en = 'The arms granted in 1959, with the British lion and the Chinese dragon, appeared on the Blue Ensign until the handover on 1 July 1997.', image_url = '/flags/history/hk-0000.png' where id = 2301 and iso_code = 'hk';
